const fs = require('node:fs');
const path = require('node:path');
const directory = path.join(__dirname, '..', 'export-templates/gdevelop');
const template = {
    project: JSON.parse(fs.readFileSync(path.join(directory, 'project-base.json'), 'utf8')),
    readme: fs.readFileSync(path.join(directory, 'README.md'), 'utf8')
};
fs.writeFileSync(path.join(__dirname, '..', 'js/gdevelopTemplate.js'),
    '// Generated by tools/build-gdevelop-template.js. Edit export-templates/gdevelop instead.\n' +
    'const gdevelopTemplate = ' + JSON.stringify(template, null, 2) + ';\n' +
    'if (typeof module !== "undefined") module.exports = gdevelopTemplate;\n');
